import React, { useState, useEffect } from 'react';
import { 
  Users, Calendar, ClipboardList, FileDown, 
  Upload, Play, Trash2, Printer, Plus, Settings, BarChart3, CalendarOff, CheckSquare, Square, Info, ShieldCheck
} from 'lucide-react';
import * as XLSX from 'xlsx';

const RosterApp = () => {
  // --- 1. STATE & PERSISTENCE ---
  const [activeTab, setActiveTab] = useState('staff');
  const [staff, setStaff] = useState(() => JSON.parse(localStorage.getItem('roster_staff')) || []);
  const [holidays, setHolidays] = useState(() => JSON.parse(localStorage.getItem('roster_holidays')) || []);
  const [leaves, setLeaves] = useState(() => JSON.parse(localStorage.getItem('roster_leaves')) || []);
  const [config, setConfig] = useState(() => JSON.parse(localStorage.getItem('roster_config')) || { 
    start: '2026-04-01', 
    end: '2026-04-30',
    weeklyHolidays: { Monday: false, Tuesday: false, Wednesday: false, Thursday: false, Friday: false, Saturday: false, Sunday: true }
  });
  const [roster, setRoster] = useState(() => JSON.parse(localStorage.getItem('persistent_roster')) || null);

  useEffect(() => {
    localStorage.setItem('roster_staff', JSON.stringify(staff));
    localStorage.setItem('roster_holidays', JSON.stringify(holidays));
    localStorage.setItem('roster_leaves', JSON.stringify(leaves));
    localStorage.setItem('roster_config', JSON.stringify(config));
    if (roster) localStorage.setItem('persistent_roster', JSON.stringify(roster));
  }, [staff, holidays, leaves, config, roster]);

  // --- 2. EXCEL IMPORT/EXPORT LOGIC (CORE FIX) ---
  
  // Helper to handle Excel's weird date serial numbers (e.g., 45382 -> 2024-04-01)
  const formatExcelDate = (serial) => {
    if (!serial) return "";
    const date = new Date(Math.round((serial - 25569) * 86400 * 1000));
    return date.toISOString().split('T')[0];
  };

  const exportTemplate = () => {
    const wb = XLSX.utils.book_new();
    
    // Staff Template Sheet
    const staffWS = XLSX.utils.json_to_sheet([
      { "Name": "Amit Sharma", "Designation": "Operator", "Level": "Senior", "Morning": "TRUE", "Evening": "TRUE", "Night": "TRUE", "WeeklyHoliday": "TRUE", "PublicHoliday": "TRUE" },
      { "Name": "Suresh Gupta", "Designation": "Junior Op", "Level": "Junior", "Morning": "FALSE", "Evening": "TRUE", "Night": "TRUE", "WeeklyHoliday": "TRUE", "PublicHoliday": "FALSE" }
    ]);
    
    // Holiday Template Sheet
    const holidayWS = XLSX.utils.json_to_sheet([
      { "Date": "2026-04-10", "Description": "Good Friday" },
      { "Date": "2026-04-14", "Description": "Ambedkar Jayanti" }
    ]);

    XLSX.utils.book_append_sheet(wb, staffWS, "Staff");
    XLSX.utils.book_append_sheet(wb, holidayWS, "Holidays");
    XLSX.writeFile(wb, "Roster_Template_System.xlsx");
  };

  const handleImport = (e) => {
    const file = e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = (evt) => {
      const bstr = evt.target.result;
      const wb = XLSX.read(bstr, { type: 'binary' });

      // Import Staff
      if (wb.SheetNames.includes("Staff")) {
        const sData = XLSX.utils.sheet_to_json(wb.Sheets["Staff"]);
        const importedStaff = sData.map((row, idx) => ({
          id: Date.now() + idx,
          name: row.Name || "Unknown",
          designation: row.Designation || "Staff",
          level: (row.Level === "Senior" || row.Level === "Junior") ? row.Level : "Junior",
          m: String(row.Morning).toUpperCase() === "TRUE",
          e: String(row.Evening).toUpperCase() === "TRUE",
          n: String(row.Night).toUpperCase() === "TRUE",
          wh: String(row.WeeklyHoliday).toUpperCase() === "TRUE",
          ph: String(row.PublicHoliday).toUpperCase() === "TRUE"
        }));
        setStaff(importedStaff);
      }

      // Import Holidays
      if (wb.SheetNames.includes("Holidays")) {
        const hData = XLSX.utils.sheet_to_json(wb.Sheets["Holidays"]);
        const importedHolidays = hData.map((row, idx) => ({
          id: Date.now() + idx + 1000,
          date: typeof row.Date === 'number' ? formatExcelDate(row.Date) : row.Date,
          desc: row.Description || "Holiday"
        }));
        setHolidays(importedHolidays);
      }
      alert("Import Successful: Staff and Holiday lists updated.");
    };
    reader.readAsBinaryString(file);
  };

  // --- 3. THE ENGINE ---
  const generateRoster = () => {
    const days = [];
    let cur = new Date(config.start);
    const stop = new Date(config.end);
    while (cur <= stop) {
      days.push(new Date(cur).toISOString().split('T')[0]);
      cur.setDate(cur.getDate() + 1);
    }

    let pool = staff.map(s => ({ ...s, lastAssigned: 0, weekTracker: {} }));

    const result = days.map(date => {
      const dayName = new Intl.DateTimeFormat('en-US', { weekday: 'long' }).format(new Date(date));
      const isPH = holidays.some(h => h.date === date);
      const isWH = config.weeklyHolidays[dayName];
      const isHoliday = isPH || isWH;
      const weekNum = Math.ceil(new Date(date).getDate() / 7);

      const assign = (shift) => {
        const candidates = pool.filter(s => {
          if (shift === 'M' && !s.m) return false;
          if (shift === 'E' && !s.e) return false;
          if (shift === 'N' && !s.n) return false;
          if (isPH && !s.ph) return false;
          if (isWH && !s.wh) return false;

          const onLeave = leaves.some(l => l.name === s.name && date >= l.start && date <= l.end && l[shift.toLowerCase()]);
          if (onLeave) return false;

          if (s.weekTracker[weekNum]) return false;
          return true;
        });

        candidates.sort((a, b) => a.lastAssigned - b.lastAssigned || (a.level === 'Junior' ? -1 : 1));

        if (candidates.length > 0) {
          const sel = candidates[0];
          sel.lastAssigned = new Date(date).getTime();
          sel.weekTracker[weekNum] = true;
          return { name: sel.name, desig: sel.designation };
        }
        return null;
      };

      return {
        date, day: dayName,
        m: isHoliday ? assign('M') : { name: "-", desig: "" },
        e: assign('E'),
        n: assign('N'),
        isHoliday
      };
    });

    setRoster(result);
    setActiveTab('roster');
  };

  return (
    <div className="max-w-[1440px] mx-auto p-4 md:p-8 bg-slate-50 min-h-screen font-sans">
      {/* HEADER WITH FUNCTIONAL BUTTONS */}
      <header className="flex justify-between items-center mb-8 print:hidden">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-900 p-3 rounded-2xl text-white shadow-lg"><ShieldCheck size={28}/></div>
          <div>
            <h1 className="text-xl font-black text-slate-900 uppercase tracking-tighter">Mumbai Roster Control</h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">Enterprise Workforce Mgmt</p>
          </div>
        </div>
        <div className="flex gap-3">
          <button onClick={exportTemplate} className="bg-white border-2 border-slate-200 px-5 py-2.5 rounded-2xl text-xs font-black flex items-center gap-2 hover:bg-slate-50 transition shadow-sm"><FileDown size={16}/> Get Template</button>
          <label className="bg-indigo-600 text-white px-6 py-2.5 rounded-2xl text-xs font-black cursor-pointer hover:bg-indigo-700 shadow-xl shadow-indigo-100 flex items-center gap-2 transition">
            <Upload size={16}/> Import Data
            <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleImport}/>
          </label>
        </div>
      </header>

      {/* NAVIGATION */}
      <nav className="flex bg-slate-200/50 p-1.5 rounded-2xl mb-8 print:hidden shadow-inner overflow-x-auto">
        {['staff', 'holidays', 'leaves', 'config', 'roster', 'summary'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 min-w-[100px] py-3 rounded-xl text-[10px] font-black uppercase transition-all ${activeTab === t ? 'bg-white text-indigo-600 shadow-md scale-[1.02]' : 'text-slate-500 hover:text-slate-800'}`}>{t}</button>
        ))}
      </nav>

      {/* MAIN CONTAINER */}
      <main className="bg-white rounded-[2.5rem] shadow-2xl border border-slate-100 min-h-[600px] overflow-hidden">
        
        {/* STAFF VIEW */}
        {activeTab === 'staff' && (
          <div className="p-8">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black uppercase tracking-tight text-slate-800">Resource Registry</h2>
              <button onClick={() => setStaff([...staff, { id: Date.now(), name: '', designation: '', level: 'Junior', m: true, e: true, n: true, wh: true, ph: true }])} className="text-indigo-600 font-black text-xs flex items-center gap-2 border-2 border-indigo-50 px-4 py-2 rounded-xl hover:bg-indigo-50 transition"><Plus size={16}/> Add Row</button>
            </div>
            <table className="w-full text-left text-xs">
              <thead className="bg-slate-50 text-slate-400 font-black uppercase text-[9px]">
                <tr><th className="p-4 border-b">S.N.</th><th className="p-4 border-b">Name</th><th className="p-4 border-b">Designation</th><th className="p-4 border-b">Level</th><th className="p-4 border-b text-center">M</th><th className="p-4 border-b text-center">E</th><th className="p-4 border-b text-center">N</th><th className="p-4 border-b text-center">WH</th><th className="p-4 border-b text-center">PH</th><th className="p-4 border-b text-right">Actions</th></tr>
              </thead>
              <tbody className="font-bold">
                {staff.map((s, i) => (
                  <tr key={s.id} className="border-b border-slate-50 hover:bg-slate-50 transition">
                    <td className="p-4 text-slate-300">{i + 1}</td>
                    <td className="p-2"><input className="w-full p-2 bg-transparent focus:bg-white rounded-lg outline-none" value={s.name} onChange={e => { const n = [...staff]; n[i].name = e.target.value; setStaff(n); }}/></td>
                    <td className="p-2"><input className="w-full p-2 bg-transparent focus:bg-white rounded-lg outline-none" value={s.designation} onChange={e => { const n = [...staff]; n[i].designation = e.target.value; setStaff(n); }}/></td>
                    <td className="p-2"><select className="bg-slate-100 p-2 rounded-lg text-[10px]" value={s.level} onChange={e => { const n = [...staff]; n[i].level = e.target.value; setStaff(n); }}><option>Senior</option><option>Junior</option></select></td>
                    {['m', 'e', 'n', 'wh', 'ph'].map(k => (<td key={k} className="p-2 text-center"><input type="checkbox" checked={s[k]} onChange={e => { const n = [...staff]; n[i][k] = e.target.checked; setStaff(n); }} className="accent-indigo-600 w-4 h-4"/></td>))}
                    <td className="p-2 text-right"><button onClick={() => setStaff(staff.filter(x => x.id !== s.id))} className="text-red-200 hover:text-red-500 p-2 transition"><Trash2 size={16}/></button></td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}

        {/* ROSTER OUTPUT VIEW */}
        {activeTab === 'roster' && (
          <div className="p-8">
            <div className="flex justify-between items-center mb-8 px-4 print:hidden">
              <h2 className="text-2xl font-black uppercase text-slate-900">Duty Chart</h2>
              <div className="flex gap-4">
                <button onClick={generateRoster} className="bg-emerald-600 text-white px-10 py-4 rounded-[1.5rem] font-black text-sm shadow-xl shadow-emerald-50 hover:bg-emerald-700 transition flex items-center gap-3"><Play size={18}/> Generate April 2026</button>
                {roster && <button onClick={() => window.print()} className="bg-slate-900 text-white p-4 rounded-2xl hover:bg-black transition"><Printer size={20}/></button>}
              </div>
            </div>

            {roster ? (
              <div className="border-[3px] border-slate-900 rounded-[2rem] overflow-hidden">
                <table className="w-full text-left text-[11px] border-collapse">
                  <thead>
                    <tr className="bg-slate-900 text-white uppercase text-[9px] tracking-widest">
                      <th className="p-6 border-r border-slate-800">Date / Day</th>
                      <th className="p-6 border-r border-slate-800 bg-emerald-900/50">Morning (Holiday)</th>
                      <th className="p-6 border-r border-slate-800 bg-amber-900/50">Evening Shift</th>
                      <th className="p-6 bg-indigo-900/50">Night Shift</th>
                    </tr>
                  </thead>
                  <tbody>
                    {roster.map((r, i) => (
                      <tr key={i} className={`border-b border-slate-100 transition ${r.isHoliday ? 'bg-red-50/50' : 'hover:bg-slate-50'}`}>
                        <td className="p-5 border-r font-black text-slate-950">
                          {r.date} <br/> <span className={`text-[8px] tracking-widest uppercase ${r.isHoliday ? 'text-red-600' : 'text-slate-400'}`}>{r.day}</span>
                        </td>
                        <td className={`p-5 border-r font-bold text-center ${r.m?.name === '-' ? 'text-slate-200' : 'text-emerald-900'}`}>
                          {r.m?.name || "-"} <br/> <span className="text-[7px] opacity-40 uppercase">{r.m?.desig}</span>
                        </td>
                        <td className="p-5 border-r font-bold text-center text-amber-900">
                          {r.e?.name || "-"} <br/> <span className="text-[7px] opacity-40 uppercase">{r.e?.desig}</span>
                        </td>
                        <td className="p-5 font-bold text-center text-indigo-900">
                          {r.n?.name || "-"} <br/> <span className="text-[7px] opacity-40 uppercase">{r.n?.desig}</span>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            ) : (
              <div className="py-40 text-center text-slate-200 font-black uppercase tracking-[0.4em]">Engine Standby</div>
            )}
          </div>
        )}

        {/* LEAVE TAB (Auto-Lookup Designation/Level) */}
        {activeTab === 'leaves' && (
          <div className="p-8">
            <div className="flex justify-between items-center mb-6">
              <h2 className="text-xl font-black uppercase text-slate-800">Leave Log</h2>
              <button onClick={() => setLeaves([...leaves, { id: Date.now(), name: '', start: '', end: '', m: true, e: true, n: true }])} className="bg-indigo-50 text-indigo-600 px-4 py-2 rounded-xl text-xs font-black"><Plus size={16}/></button>
            </div>
            <table className="w-full text-left text-xs">
              <thead className="bg-slate-50 text-slate-400 font-black uppercase">
                <tr><th className="p-4 border-b">S.N.</th><th className="p-4 border-b">Name</th><th className="p-4 border-b">Desig.</th><th className="p-4 border-b">Level</th><th className="p-4 border-b">From</th><th className="p-4 border-b">To</th><th className="p-4 border-b text-center">M</th><th className="p-4 border-b text-center">E</th><th className="p-4 border-b text-center">N</th><th className="p-4 border-b text-right">Del</th></tr>
              </thead>
              <tbody className="font-bold">
                {leaves.map((l, i) => {
                  const sInfo = staff.find(st => st.name === l.name) || {};
                  return (
                    <tr key={l.id} className="border-b border-slate-50">
                      <td className="p-4 text-slate-300">{i + 1}</td>
                      <td className="p-2"><select className="w-full p-2 bg-slate-50 rounded-lg outline-none" value={l.name} onChange={e => { const n = [...leaves]; n[i].name = e.target.value; setLeaves(n); }}><option value="">-Select-</option>{staff.map(s => <option key={s.id}>{s.name}</option>)}</select></td>
                      <td className="p-4 text-slate-400 italic">{sInfo.designation || '-'}</td>
                      <td className="p-4 text-slate-400 italic">{sInfo.level || '-'}</td>
                      <td className="p-2"><input type="date" className="p-2 bg-slate-50 rounded-lg" value={l.start} onChange={e => { const n = [...leaves]; n[i].start = e.target.value; setLeaves(n); }}/></td>
                      <td className="p-2"><input type="date" className="p-2 bg-slate-50 rounded-lg" value={l.end} onChange={e => { const n = [...leaves]; n[i].end = e.target.value; setLeaves(n); }}/></td>
                      {['m', 'e', 'n'].map(k => (<td key={k} className="p-2 text-center"><input type="checkbox" checked={l[k]} onChange={e => { const n = [...leaves]; n[i][k] = e.target.checked; setLeaves(n); }} className="accent-red-500 w-4 h-4"/></td>))}
                      <td className="p-2 text-right"><button onClick={() => setLeaves(leaves.filter(x => x.id !== l.id))} className="text-red-200 p-2"><Trash2 size={16}/></button></td>
                    </tr>
                  )
                })}
              </tbody>
            </table>
          </div>
        )}

        {/* SUMMARY TAB */}
        {activeTab === 'summary' && (
          <div className="p-8">
            <h2 className="text-xl font-black uppercase mb-8">Workload Distribution</h2>
            {roster ? (
              <table className="w-full text-left text-xs">
                <thead>
                  <tr className="bg-slate-900 text-white uppercase text-[9px] tracking-widest">
                    <th className="p-5">S.N.</th><th className="p-5">Member</th><th className="p-5 text-center">M</th><th className="p-5 text-center">E</th><th className="p-5 text-center">N</th><th className="p-5 text-center bg-slate-800">Total</th>
                  </tr>
                </thead>
                <tbody className="font-bold">
                  {staff.map((s, i) => {
                    const m = roster.filter(r => r.m?.name === s.name).length;
                    const e = roster.filter(r => r.e?.name === s.name).length;
                    const n = roster.filter(r => r.n?.name === s.name).length;
                    return (
                      <tr key={s.id} className="border-b border-slate-50 hover:bg-slate-50">
                        <td className="p-5 text-slate-300">{i + 1}</td>
                        <td className="p-5 text-indigo-950 font-black">{s.name}<br/><span className="text-[9px] font-normal text-slate-400">{s.designation}</span></td>
                        <td className="p-5 text-center text-emerald-600">{m}</td>
                        <td className="p-5 text-center text-amber-600">{e}</td>
                        <td className="p-5 text-center text-indigo-600">{n}</td>
                        <td className="p-5 text-center font-black bg-slate-50 text-slate-900">{m + e + n}</td>
                      </tr>
                    )
                  })}
                </tbody>
              </table>
            ) : (
              <div className="py-20 text-center text-slate-300 font-black uppercase tracking-widest">Generate Roster to See Statistics</div>
            )}
          </div>
        )}

        {/* CONFIG TAB */}
        {activeTab === 'config' && (
          <div className="p-16 max-w-2xl mx-auto space-y-12">
            <h2 className="text-2xl font-black text-slate-900 border-b pb-6 uppercase tracking-widest text-center">Settings</h2>
            <div className="grid grid-cols-2 gap-8">
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Start Date</label>
                <input type="date" className="w-full p-5 bg-slate-100 border-none rounded-2xl font-black text-xl" value={config.start} onChange={e => setConfig({...config, start: e.target.value})}/>
              </div>
              <div className="space-y-4">
                <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">End Date</label>
                <input type="date" className="w-full p-5 bg-slate-100 border-none rounded-2xl font-black text-xl" value={config.end} onChange={e => setConfig({...config, end: e.target.value})}/>
              </div>
            </div>
            <div className="space-y-6">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em] block text-center">Weekly Holidays (Morning Shift Active)</label>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {Object.keys(config.weeklyHolidays).map(day => (
                  <button key={day} onClick={() => setConfig({...config, weeklyHolidays: {...config.weeklyHolidays, [day]: !config.weeklyHolidays[day]}})} className={`flex items-center justify-between p-4 rounded-xl border-2 transition-all ${config.weeklyHolidays[day] ? 'bg-indigo-600 border-indigo-600 text-white' : 'bg-white border-slate-100 text-slate-400'}`}>
                    <span className="text-[10px] font-black uppercase">{day.substring(0,3)}</span>
                    {config.weeklyHolidays[day] ? <CheckSquare size={16}/> : <Square size={16}/>}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

      </main>
    </div>
  );
};

export default RosterApp;